function Invoke-CmakeReject([string]$Name,[string[]]$Vector,[string]$ExpectedText,[string]$ScriptPath){if($Vector.Count -ne 6 -or '-P' -notin $Vector -or $ScriptPath -notin $Vector){throw "$Name argv mode/count guard failed"};$record=[pscustomobject]@{name=$Name;cwd=(Get-Location).Path;executable='cmake.exe';argv=$Vector;argv_count=$Vector.Count;expected_diagnostic=$ExpectedText;started=(Get-Date).ToString('o')};$record|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "$Name.argv.json") -Encoding utf8;$sw=[Diagnostics.Stopwatch]::StartNew();& cmake.exe @Vector *> (Join-Path $ev "$Name.log");$native=$LASTEXITCODE;$sw.Stop();$result=[pscustomobject]@{name=$Name;argv_count=$Vector.Count;exitcode=$native;elapsed_seconds=$sw.Elapsed.TotalSeconds;expected_text=$ExpectedText;diagnostic_found=((Get-Content -LiteralPath (Join-Path $ev "$Name.log") -Raw).Contains($ExpectedText))};$result|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "$Name.result.json") -Encoding utf8;$native|Set-Content -LiteralPath (Join-Path $ev "$Name.exitcode") -NoNewline;$sw.Elapsed.TotalSeconds.ToString('F6',[Globalization.CultureInfo]::InvariantCulture)|Set-Content -LiteralPath (Join-Path $ev "$Name.elapsed.txt") -NoNewline;return $result}
