$results=@();foreach($c in $cases){if(Test-Path -LiteralPath $c.output){throw "$($c.name) output preexists"};$v=[string[]]@("-DJE_LUA_SOURCE_ARCHIVE:FILEPATH=$($c.source)","-DJE_LUA_SOURCE_SHA256=$($c.sha)","-DJE_LUA_SOURCE_URL=$url","-DJE_LUA_OUTPUT:PATH=$($c.output)",'-P',(Join-Path $root $cmake));$r=Invoke-CmakeReject $c.name $v $c.expected (Join-Path $root $cmake);$afterExists=Test-Path -LiteralPath $c.output;$r|Add-Member -NotePropertyName output_created_after -NotePropertyValue $afterExists;if($r.exitcode -eq 0 -or -not $r.diagnostic_found -or $afterExists){throw "$($c.name) rejection contract failed"};$results+=,$r}
